mapper.select:
SELECT MENU_ID,PARENT_MENU_ID,ROUTE_NAME,MENU_NAME,MENU_TYPE,"PATH","RANK",REMARK,HIDE,STATUS,ADMIN_FLAG
FROM A1MFG.SYS_MENU_LIST WHERE 1=1 AND ( 1 != 1

    OR MENU_ID = #{menuId}


    OR PATH = #{path}


    OR MENU_NAME = #{menuName}

) AND PARENT_MENU_ID = #{parentMenuId}

mapper.update:
UPDATE A1MFG.SYS_MENU_LIST
SET UPDATE_USER = #{updateUser},UPDATE_TIME = SYSDATE

    ,ROUTE_NAME = #{routeName}


    ,MENU_NAME = #{menuName}


    ,MENU_TYPE = #{menuType}


    ,PATH = #{path}


    ,RANK = #{rank}


    ,REMARK = #{remark}


    ,HIDE = #{hide}


    ,STATUS = #{status}


    ,ADMIN_FLAG = #{adminFlag}

WHERE MENU_ID = #{menuId}
